// Table designer tab (docs/PLAN-M1.5.md 1.3.1): header, column grid, keys/indexes/FKs/checks, live DDL preview and
// Apply (Ctrl+S). The preview is generated by the engine (POST .../designer/table/script, debounced 250 ms) and is
// what Apply runs, verbatim when edited by hand.
import { Code2, LoaderCircle, Play, RefreshCw, Table2 } from 'lucide-react';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { api, errorMessage, isApiError } from '../../api/client';
import type {
  DdlFailedDetail, DesignerType, DesignerTypesResponse, Dialect, TableColumnModel, TableModel, TableScriptResponse,
} from '../../api/types';
import { catalogDatabase } from '../../app/actions';
import { runCommand } from '../../commands/registry';
import { commandView } from '../../commands/useCommands';
import { confirmItemList } from '../../components/common/ConfirmDialog';
import { Select } from '../../components/common/Select';
import { Kbd } from '../../components/Shortcuts/Kbd';
import type { TabViewProps } from '../../components/layout/tabViews';
import { dbKey, useCatalog, useSnapshot } from '../../store/catalog';
import { useConnection, useDialect } from '../../store/connections';
import { useTabs } from '../../store/tabs';
import { toast, useUi } from '../../store/ui';
import { applySummary, scriptToText, splitForApply } from '../ddl';
import { DdlPreview, type ApplyFailure } from '../DdlPreview';
import { registerDesignerActions } from '../actions';
import { designerKey, tableTitle, type TableDesignerState } from '../open';
import { ColumnGrid } from './ColumnGrid';
import { confirmItems, recreatedSummary } from './confirmSummary';
import { ChecksPanel, ForeignKeysPanel, KeysPanel } from './ConstraintsPanel';
import {
  addColumn, catalogTypes, duplicateColumn, hasErrors, isArrayType, moveColumn, newTableModel, removeColumn, sameModel, togglePrimaryKey, updateColumn,
  validateTable, visibleIssues, withArray, withIds,
} from './model';

type Section = 'columns' | 'keys' | 'fks' | 'checks';

const typesCache = new Map<string, Promise<DesignerTypesResponse | null>>();

function loadTypes(connectionId: string, database: string | null): Promise<DesignerTypesResponse | null> {
  const k = `${connectionId}\u0001${database ?? ''}`;
  let p = typesCache.get(k);
  if (!p) {
    p = api.designerTypes(connectionId, database).catch((e) => {
      console.warn('[designer] type list unavailable', e);
      typesCache.delete(k);
      return null;
    });
    typesCache.set(k, p);
  }
  return p;
}

const FALLBACK_TYPES: Record<Dialect, string[]> = {
  tsql: ['int', 'bigint', 'smallint', 'tinyint', 'bit', 'decimal(18,2)', 'money', 'float', 'real', 'nvarchar(100)', 'varchar(100)', 'nchar(10)', 'nvarchar(max)', 'date', 'datetime2(3)', 'datetimeoffset(7)', 'time(7)', 'uniqueidentifier', 'varbinary(max)', 'xml'],
  plsql: ['NUMBER(10)', 'NUMBER(19)', 'NUMBER(12,2)', 'NUMBER', 'BINARY_DOUBLE', 'VARCHAR2(100)', 'NVARCHAR2(100)', 'CHAR(1)', 'CLOB', 'DATE', 'TIMESTAMP(6)', 'TIMESTAMP(6) WITH TIME ZONE', 'RAW(16)', 'BLOB', 'BOOLEAN'],
  sqlite: ['INTEGER', 'TEXT', 'REAL', 'NUMERIC', 'BLOB', 'BOOLEAN', 'DATETIME', 'DATE', 'JSON'],
  // The engine's PgDdlScripter.GetTypes list (docs/PLAN-PG.md 2.7), used while GET /designer/types is unavailable.
  pgsql: [
    'smallint', 'integer', 'bigint', 'numeric(12,2)', 'real', 'double precision', 'boolean', 'text', 'varchar(100)', 'char(10)', 'uuid', 'date',
    'timestamp(3)', 'timestamptz(3)', 'time', 'timetz', 'interval', 'bytea', 'json', 'jsonb', 'xml', 'inet', 'cidr', 'macaddr', 'money',
  ],
};

function fallbackTypes(dialect: Dialect): DesignerType[] {
  return FALLBACK_TYPES[dialect].map((t) => ({ name: t.replace(/\(.*$/, ''), default: t, params: /\(/.test(t) ? 'length' : 'none', category: 'other' }));
}


export function TableDesignerView({ tab, theme, visible }: TabViewProps) {
  const st = tab.state as TableDesignerState;
  const cid = st.connectionId;
  const conn = useConnection(cid);
  const dialect = useDialect(cid);
  const catalogDb = catalogDatabase(cid, st.database);
  const snapshot = useSnapshot(cid, catalogDb);
  /** Every schema of the database (GET /catalog/schemas), not only the loaded ones. */
  const schemaNames = useCatalog((s) => s.dbs[dbKey(cid, catalogDb)]?.schemasResp?.schemas);
  const askConfirm = useUi((s) => s.askConfirm);

  const [original, setOriginal] = useState<TableModel | null>((st.original as TableModel | undefined) ?? null);
  const [desired, setDesired] = useState<TableModel | null>((st.desired as TableModel | undefined) ?? null);
  const initialNew = useRef<TableModel | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [types, setTypes] = useState<DesignerTypesResponse | null>(null);
  const [section, setSection] = useState<Section>('columns');
  const [activeCol, setActiveCol] = useState(0);
  const [script, setScript] = useState<TableScriptResponse | null>(null);
  const [scriptLoading, setScriptLoading] = useState(false);
  const [scriptError, setScriptError] = useState<string | null>(null);
  const [generated, setGenerated] = useState('');
  const [text, setText] = useState(st.preview ?? '');
  const [handEdited, setHandEdited] = useState(!!st.preview);
  const [applying, setApplying] = useState(false);
  const [failure, setFailure] = useState<ApplyFailure | null>(null);
  /** Validation shows after the user left the Name field or tried to apply (not on a pristine new table). */
  const [nameTouched, setNameTouched] = useState(false);
  const [applyTried, setApplyTried] = useState(false);
  const lines = useRef<number[]>([]);

  // ---------- load ----------
  const load = useCallback(async () => {
    setLoadError(null);
    if (!st.name) {
      const t = newTableModel(dialect, st.schema);
      initialNew.current = t;
      setOriginal(null);
      setDesired((d) => d ?? t);
      return;
    }
    try {
      const m = withIds(await api.designerTable(cid, st.database, st.schema, st.name));
      setOriginal(m);
      setDesired(m);
      setHandEdited(false);
      setFailure(null);
    } catch (e) {
      setLoadError(errorMessage(e));
    }
  }, [cid, st.database, st.schema, st.name, dialect]);

  useEffect(() => {
    if (desired && (original || !st.name)) {
      if (!st.name) initialNew.current ??= newTableModel(dialect, st.schema);
      return;
    }
    void load();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    let live = true;
    void loadTypes(cid, st.database).then((t) => live && setTypes(t));
    return () => {
      live = false;
    };
  }, [cid, st.database]);

  const typeList = useMemo(() => {
    const base = types?.types.length ? types.types : fallbackTypes(dialect);
    const user = catalogTypes(snapshot).filter((u) => !base.some((b) => b.name === u.name));
    return user.length ? [...base, ...user] : base;
  }, [types, dialect, snapshot]);
  const features = types?.features ?? null;
  const issues = useMemo(() => (desired ? validateTable(desired, dialect) : []), [desired, dialect]);
  const blocking = hasErrors(issues);
  const shownIssues = visibleIssues(issues, { existing: !!original, nameTouched, applyTried });
  const shownBlocking = hasErrors(shownIssues);
  const dirty = !!desired && (handEdited || (original ? !sameModel(original, desired) : !sameModel(initialNew.current, desired)));

  // ---------- live preview ----------
  useEffect(() => {
    if (!desired || handEdited) return;
    if (blocking) {
      setScript(null);
      setScriptError(null);
      setGenerated('');
      setText('');
      return;
    }
    const ac = new AbortController();
    const timer = setTimeout(async () => {
      setScriptLoading(true);
      try {
        const s = await api.scriptTable(cid, { database: st.database, original, desired }, ac.signal);
        const p = scriptToText(s.statements, dialect);
        lines.current = p.lines;
        setScript(s);
        setScriptError(null);
        setGenerated(p.text);
        setText(p.text);
      } catch (e) {
        if (isApiError(e, 'ABORTED')) return;
        setScriptError(errorMessage(e));
      } finally {
        if (!ac.signal.aborted) setScriptLoading(false);
      }
    }, 250);
    return () => {
      clearTimeout(timer);
      ac.abort();
    };
  }, [desired, original, handEdited, blocking, cid, st.database, dialect]);

  // ---------- persist into the tab (workspace) ----------
  useEffect(() => {
    const t = setTimeout(() => {
      useTabs.getState().updateView(tab.id, {
        dirty,
        state: { ...st, desired: desired ?? undefined, original: original ?? undefined, preview: handEdited ? text : null } satisfies TableDesignerState,
      });
    }, 300);
    return () => clearTimeout(t);
  }, [desired, original, handEdited, text, dirty]); // eslint-disable-line react-hooks/exhaustive-deps

  const edit = (fn: (t: TableModel) => TableModel) => {
    if (handEdited) return;
    setFailure(null);
    setDesired((d) => (d ? fn(d) : d));
  };

  // ---------- apply ----------
  const apply = useCallback(async () => {
    if (!desired || applying) return;
    setApplyTried(true);
    if (blocking && !handEdited) {
      toast('warning', 'Fix the problems in the designer first', issues.filter((i) => i.severity === 'error').map((i) => i.message).join('\n'));
      return;
    }
    const statements = handEdited
      ? splitForApply(text, dialect)
      : (script?.statements ?? []).map((s, i) => ({ sql: s.sql, line: lines.current[i] ?? null }));
    if (!statements.length) {
      toast('info', 'Nothing to apply', 'The table already matches the design.');
      return;
    }
    const destructive = !handEdited && (script?.rebuildRequired || script?.statements.some((s) => s.kind === 'drop'));
    if (destructive) {
      const recreated = script?.rebuildRequired ? recreatedSummary(script.statements) : '';
      const ok = await askConfirm({
        title: script?.rebuildRequired ? 'Rebuild the table?' : 'Drop columns or constraints?',
        message: script?.rebuildRequired
          ? `${desired.name} is copied into a new table, the old one is dropped and the copy renamed. Data, indexes and triggers are carried over.${recreated ? ` ${recreated}` : ''}`
          : 'The script drops objects; data in dropped columns is lost.',
        // SQL first lines as code, the scripter's annotations ("Keeps the AUTOINCREMENT counter…") as notes
        items: confirmItemList(confirmItems(script?.statements ?? [])),
        confirmLabel: 'Apply',
        danger: true,
      });
      if (!ok) return;
    }
    setApplying(true);
    setFailure(null);
    const transactional = script?.transactional ?? dialect !== 'plsql';
    try {
      const r = await api.applyDdl(cid, { database: st.database, statements: statements.map((s) => s.sql), transactional, schema: desired.schema });
      const name = desired.name;
      toast('success', `${original ? 'Altered' : 'Created'} ${name}`, `${r.executed} statement${r.executed === 1 ? '' : 's'} in ${r.elapsedMs} ms`);
      const nextState: TableDesignerState = { ...st, schema: desired.schema, name, desired: undefined, original: undefined, preview: null };
      useTabs.getState().updateView(tab.id, {
        title: tableTitle(dialect, desired.schema, name), state: nextState, dirty: false,
        key: designerKey('table', { connectionId: cid, database: st.database, schema: desired.schema }, name),
      });
      setApplyTried(false);
      try {
        const m = withIds(await api.designerTable(cid, st.database, desired.schema, name));
        setOriginal(m);
        setDesired(m);
      } catch {
        setOriginal(desired);
      }
      setHandEdited(false);
      if (desired.schema) void useCatalog.getState().loadSchema(cid, catalogDb, desired.schema, true);
    } catch (e) {
      const detail = isApiError(e, 'DDL_FAILED') ? (e.detail as DdlFailedDetail) : null;
      const failed = detail ? statements[detail.failedIndex] : null;
      setFailure({
        message: detail?.providerError?.message ?? errorMessage(e),
        detail,
        line: failed?.line ?? null,
        executed: detail && !detail.rolledBack ? statements.slice(0, detail.executed).map((s) => s.sql) : [],
      });
      toast('error', 'Apply failed', detail?.providerError?.message ?? errorMessage(e));
    } finally {
      setApplying(false);
    }
  }, [desired, original, applying, blocking, handEdited, text, script, dialect, cid, st, tab.id, catalogDb, issues, askConfirm]);

  useEffect(() => registerDesignerActions(tab.id, { apply: () => void apply() }), [tab.id, apply]);

  if (!visible && !desired) return null;
  const schemas = [...new Set([...(snapshot?.schemas.map((s) => s.name) ?? []), ...(schemaNames?.map((s) => s.name) ?? []), ...(desired?.schema ? [desired.schema] : [])])].sort((a, b) => a.localeCompare(b));
  const col = desired?.columns[activeCol] ?? null;
  const errorRows = new Set(shownIssues.filter((i) => i.severity === 'error' && i.column !== undefined).map((i) => i.column!));
  const nameInvalid = shownIssues.some((i) => i.field === 'name');
  const locked = handEdited || applying;
  const counts = { keys: (desired?.uniques.length ?? 0) + (desired?.indexes.length ?? 0) + (desired?.primaryKey ? 1 : 0), fks: desired?.foreignKeys.length ?? 0, checks: desired?.checks.length ?? 0 };

  return (
    <div className="dz" style={{ display: visible ? undefined : 'none' }} data-command-scope="designer" aria-label={tab.title}>
      <div className="dz-header">
        <div className="dz-title">
          <Table2 size={16} aria-hidden="true" />
          <span>{original ? 'Design table' : 'New table'}</span>
          <span className="dz-sub">
            {conn?.name ?? ''}
            {st.database ? ` · ${st.database}` : ''}
          </span>
        </div>
        {desired && (
          <>
            <label className="dz-field">
              Name
              <input
                className="input mono"
                style={{ width: 200 }}
                value={desired.name}
                placeholder={dialect === 'plsql' ? 'TABLE_NAME' : dialect === 'pgsql' ? 'table_name' : 'TableName'}
                disabled={locked}
                autoFocus={!original}
                aria-invalid={nameInvalid || undefined}
                onBlur={() => setNameTouched(true)}
                onChange={(e) => edit((t) => ({ ...t, name: e.target.value }))}
              />
            </label>
            {dialect !== 'sqlite' || schemas.length > 1 ? (
              <label className="dz-field">
                Schema
                <Select
                  value={desired.schema ?? ''}
                  disabled={locked || !!original}
                  options={(schemas.length ? schemas : [desired.schema ?? '']).map((s) => ({ value: s, label: s || '(default)' }))}
                  onChange={(v) => edit((t) => ({ ...t, schema: v || null }))}
                  menuMinWidth={160}
                />
              </label>
            ) : null}
            {features?.comments !== false && dialect !== 'sqlite' && (
              <label className="dz-field">
                Comment
                <input className="input" style={{ width: 220 }} value={desired.comment ?? ''} disabled={locked} onChange={(e) => edit((t) => ({ ...t, comment: e.target.value || null }))} />
              </label>
            )}
            {dialect === 'sqlite' && (
              <>
                <label className="check sm" title="Store rows in the primary key B-tree (needs a primary key)">
                  <input type="checkbox" checked={desired.options.withoutRowid} disabled={locked} onChange={(e) => edit((t) => ({ ...t, options: { ...t.options, withoutRowid: e.target.checked } }))} />
                  WITHOUT ROWID
                </label>
                <label className="check sm" title="Enforce column types (SQLite 3.37+)">
                  <input type="checkbox" checked={desired.options.strict} disabled={locked} onChange={(e) => edit((t) => ({ ...t, options: { ...t.options, strict: e.target.checked } }))} />
                  STRICT
                </label>
              </>
            )}
            {(dialect === 'plsql' || dialect === 'pgsql') && (
              <label className="dz-field">
                Tablespace
                <input className="input mono" style={{ width: 120 }} value={desired.options.tablespace ?? ''} disabled={locked} onChange={(e) => edit((t) => ({ ...t, options: { ...t.options, tablespace: e.target.value || null } }))} />
              </label>
            )}
          </>
        )}
        <span className="dz-spacer" />
        {original && (
          <>
            <button
              type="button"
              className="btn btn-xs"
              title="Generate code for this table"
              onClick={() => runCommand('codegen.open', { kind: 'object', connectionId: cid, database: st.database, ref: { database: st.database, schema: original.schema, name: original.name, type: 'table' } })}
            >
              <Code2 size={12} /> Code
            </button>
            <button
              type="button"
              className="icon-btn"
              title="Reload from the server (discards changes)"
              aria-label="Reload from the server"
              onClick={async () => {
                if (dirty && !(await askConfirm({ title: 'Discard changes?', message: 'Reloading replaces your design with the table as it is on the server.', confirmLabel: 'Reload', danger: true }))) return;
                void load();
              }}
            >
              <RefreshCw size={14} />
            </button>
          </>
        )}
        <button
          type="button"
          className="btn btn-primary btn-xs"
          disabled={!desired || applying || (!handEdited && !blocking && !script?.statements.length)}
          onClick={() => void apply()}
          title={commandView('designer.apply', undefined, blocking && !handEdited ? 'Apply — shows what to fix first' : 'Apply the DDL').tooltip}
        >
          {applying ? <LoaderCircle size={12} className="spin" /> : <Play size={12} />} Apply
        </button>
      </div>

      {loadError ? (
        <div className="dz-empty" role="alert">
          <span>Could not load the table: {loadError}</span>
          <button type="button" className="btn btn-xs" onClick={() => void load()}>
            <RefreshCw size={12} /> Retry
          </button>
        </div>
      ) : !desired ? (
        <div className="dz-empty">
          <LoaderCircle size={16} className="spin" aria-label="Loading table" />
        </div>
      ) : (
        <div className="dz-body">
          <div className="dz-top">
            <div className="dz-sections" role="tablist" aria-label="Table parts">
              {(
                [
                  ['columns', `Columns`, desired.columns.length],
                  ['keys', 'Keys & Indexes', counts.keys],
                  ['fks', 'Foreign Keys', counts.fks],
                  ['checks', 'Checks', counts.checks],
                ] as const
              ).map(([id, label, n]) => (
                <button key={id} type="button" role="tab" aria-selected={section === id} className={`results-tab${section === id ? ' active' : ''}`} onClick={() => setSection(id)}>
                  {label}
                  <span className="results-tab-count">{n}</span>
                </button>
              ))}
            </div>
            <div className={`dz-section-body${locked ? ' dz-locked' : ''}`} aria-disabled={locked || undefined}>
              {section === 'columns' && (
                <ColumnGrid
                  table={desired}
                  dialect={dialect}
                  types={typeList}
                  features={features}
                  readOnly={locked}
                  errorRows={errorRows}
                  active={activeCol}
                  onActiveChange={setActiveCol}
                  onChange={(i, patch) => edit((t) => updateColumn(t, i, patch, dialect))}
                  onTogglePk={(i) => edit((t) => togglePrimaryKey(t, i, dialect))}
                  onAdd={(at) => {
                    edit((t) => addColumn(t, dialect, at));
                    setActiveCol(Math.max(0, Math.min(at, desired.columns.length)));
                  }}
                  onRemove={(i) => edit((t) => removeColumn(t, i))}
                  onMove={(i, d) => edit((t) => moveColumn(t, i, d))}
                  onDuplicate={(i) => {
                    edit((t) => duplicateColumn(t, i, dialect));
                    setActiveCol(i + 1);
                  }}
                />
              )}
              {section === 'keys' && <KeysPanel table={desired} dialect={dialect} features={features} readOnly={locked} catalog={snapshot} onChange={(t) => edit(() => t)} />}
              {section === 'fks' && <ForeignKeysPanel table={desired} dialect={dialect} features={features} readOnly={locked} catalog={snapshot} onChange={(t) => edit(() => t)} />}
              {section === 'checks' && <ChecksPanel table={desired} dialect={dialect} features={features} readOnly={locked} catalog={snapshot} onChange={(t) => edit(() => t)} />}
            </div>
            {section === 'columns' && col && (
              <ColumnProps col={col} dialect={dialect} features={features} readOnly={locked} onChange={(patch) => edit((t) => updateColumn(t, activeCol, patch, dialect))} />
            )}
            {section === 'columns' && (
              <div className="dz-hint">
                <kbd>Enter</kbd> edit · <kbd>Tab</kbd> next cell · <kbd>Space</kbd> toggle · <kbd>Insert</kbd> add · <kbd>Alt+Insert</kbd> insert below · <kbd>Del</kbd> remove · <kbd>Alt+↑/↓</kbd> reorder ·{' '}
                <Kbd shortcut="Mod+D" /> duplicate · <Kbd shortcut={commandView('designer.apply').shortcut ?? 'Mod+S'} /> apply
              </div>
            )}
            {shownIssues.length > 0 && (
              <div className={`dz-banner ${shownBlocking ? 'error' : 'warning'}`} role={shownBlocking ? 'alert' : 'status'}>
                <ul className="dz-issues">
                  {shownIssues.map((i, k) => (
                    <li key={k}>{i.message}</li>
                  ))}
                </ul>
              </div>
            )}
          </div>
          <DdlPreview
            tabId={tab.id}
            dialect={dialect}
            theme={theme}
            text={blocking && !handEdited ? '' : text}
            handEdited={handEdited}
            loading={scriptLoading}
            summary={
              handEdited
                ? `${splitForApply(text, dialect).length} statement(s) (edited)`
                : blocking
                  ? shownBlocking
                    ? 'Fix the problems above to see the DDL'
                    : 'Name the table to see its DDL'
                  : script
                    ? applySummary(script, dialect)
                    : ''
            }
            empty={!handEdited && !scriptError && !failure && (blocking || !script?.statements.length)}
            warnings={handEdited ? [] : [...(script?.warnings ?? [])]}
            error={scriptError}
            failure={failure}
            onChange={(t) => {
              if (t === text) return;
              setText(t);
              if (t !== generated && !(blocking && !handEdited)) setHandEdited(true);
            }}
            onRegenerate={() => {
              setHandEdited(false);
              setText(generated);
              setFailure(null);
            }}
          />
        </div>
      )}
    </div>
  );
}

/** Properties of the focused column that do not fit in the grid. */
function ColumnProps({ col, dialect, features, readOnly, onChange }: { col: TableColumnModel; dialect: Dialect; features: DesignerTypesResponse['features'] | null; readOnly: boolean; onChange(p: Partial<TableColumnModel>): void }) {
  const computedAllowed = features?.computed ?? dialect !== 'sqlite';
  return (
    <div className="dz-props" aria-label={`Properties of ${col.name || 'column'}`}>
      <span className="dz-props-title">{col.name || 'Column'}</span>
      {col.identity && (
        <>
          <label className="dz-field">
            Seed
            <input className="input xs" type="number" style={{ width: 64 }} value={col.identity.seed} disabled={readOnly} onChange={(e) => onChange({ identity: { ...col.identity!, seed: Number(e.target.value) || 0 } })} />
          </label>
          <label className="dz-field">
            Increment
            <input className="input xs" type="number" style={{ width: 64 }} value={col.identity.increment} disabled={readOnly} onChange={(e) => onChange({ identity: { ...col.identity!, increment: Number(e.target.value) || 1 } })} />
          </label>
          {(dialect === 'plsql' || dialect === 'pgsql') && (
            <label className="check sm" title={col.identity.always ? 'GENERATED ALWAYS AS IDENTITY: inserts cannot supply a value' : 'GENERATED BY DEFAULT AS IDENTITY: inserts may supply a value'}>
              <input type="checkbox" checked={!!col.identity.always} disabled={readOnly} onChange={(e) => onChange({ identity: { ...col.identity!, always: e.target.checked } })} />
              ALWAYS
            </label>
          )}
        </>
      )}
      {computedAllowed && (
        <label className="dz-field">
          Computed
          <input
            className="input xs mono"
            style={{ width: 220 }}
            placeholder="expression"
            title="An expression makes the column computed"
            value={col.computed?.expression ?? ''}
            disabled={readOnly}
            onChange={(e) => onChange({ computed: e.target.value ? { expression: e.target.value, persisted: dialect === 'pgsql' || (col.computed?.persisted ?? false) } : null })}
          />
        </label>
      )}
      {col.computed && (
        <label className="check sm" title={dialect === 'pgsql' ? 'PostgreSQL generated columns are STORED' : undefined}>
          <input
            type="checkbox"
            checked={dialect === 'pgsql' || col.computed.persisted}
            disabled={readOnly || dialect === 'pgsql'}
            onChange={(e) => onChange({ computed: { ...col.computed!, persisted: e.target.checked } })}
          />
          {dialect === 'plsql' || dialect === 'pgsql' ? 'Stored' : 'Persisted'}
        </label>
      )}
      {dialect === 'pgsql' && !col.computed && (
        <label className="check sm" title="Array of the type (appends [] to the type text)">
          <input type="checkbox" checked={isArrayType(col.type)} disabled={readOnly || !col.type.trim()} onChange={(e) => onChange({ type: withArray(col.type, e.target.checked) })} />
          Array
        </label>
      )}
      {dialect !== 'plsql' && (
        <label className="dz-field">
          Collation
          <input className="input xs mono" style={{ width: 160 }} value={col.collation ?? ''} disabled={readOnly} onChange={(e) => onChange({ collation: e.target.value || null })} />
        </label>
      )}
      {dialect === 'tsql' && col.default && (
        <label className="dz-field">
          Default name
          <input className="input xs mono" style={{ width: 180 }} placeholder="DF_… (generated)" value={col.defaultName ?? ''} disabled={readOnly} onChange={(e) => onChange({ defaultName: e.target.value || null })} />
        </label>
      )}
      {dialect === 'sqlite' && col.comment !== null && (
        <label className="dz-field">
          Comment
          <input className="input xs" style={{ width: 200 }} value={col.comment ?? ''} disabled={readOnly} onChange={(e) => onChange({ comment: e.target.value || null })} />
        </label>
      )}
    </div>
  );
}
